// Copies the closed-loop report (krishna_report.html, generated by krishna_metrics.py in the
// closed-loop repo) into public/closed-loop-report/ so the preview's Closed Loop page can show the
// real report, exactly as built, instead of a simplified re-creation.
//
// The report carries real client names, part numbers and shop data, and this repo is public — so
// the copy is git-ignored and deploy-preview.js strips it from anything it publishes.
//
//   npm run sync:closed-loop                     uses ../../closed-loop/krishna_report.html
//   npm run sync:closed-loop -- <path-to.html>   uses that file

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const source = path.resolve(process.argv[2] || path.join(root, '..', '..', 'closed-loop', 'krishna_report.html'));
const outDir = path.join(root, 'public', 'closed-loop-report');

if (!fs.existsSync(source)) {
  console.error(`Report not found: ${source}`);
  process.exit(1);
}
fs.mkdirSync(outDir, { recursive: true });
fs.copyFileSync(source, path.join(outDir, 'index.html'));
console.log(`Copied ${source}\n    -> ${path.join(outDir, 'index.html')} (${Math.round(fs.statSync(source).size / 1024)} KB)`);
